Method.Implementation:
	set tSC = $$$OK

	Do ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).CheckSvnSetup(userNm, passwd)
	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(userNm, "GetDeploymentPackageFromSvn - CheckInDeploymentPackageFile: " _ fileNm)

	if ('##class(%File).Exists(..DeployDirectory _ ..DeploymentPackageDirec))
	{
		Do ##class(%File).CreateDirectoryChain(..DeployDirectory _ ..DeploymentPackageDirec)
	}
	set fullPath = $$$USRRELEASEBASEDIR _ userNm _ $$$SVNSRCTRUNK _ ..DeploymentPackageDirec _ fileNm
	Do ##class(%File).Delete(fullPath)
	Set cmd=""
	if (rev '= "")
	{

		Set cmd= $$$SVNUPDATE _ " --revision " _ rev
	}
	else
	{	
		Set cmd= $$$SVNUPDATE	
		//  set tSC = $$$ERROR($$$GeneralError, "Checkout: Revision number is required") 
	}	
	Set cmd= cmd _ " --username " _ %session.Data("svnUsrNm") _ " --password '" _ %session.Data("svnPsWd") _ "' " _  fullPath 

	Set status = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( cmd)

	if (status '= 0)
	{
		set tSC = $$$ERROR($$$GeneralError, $$$SVNUPDATE _ " --revision " _ rev _ " failed")
	}
	if ##class(%File).Exists(fullPath)
	{
		if (rev = "")
		{
			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(userNm,   "Checked out latest version of " _ fileNm)
		}
		else
		{
			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(userNm,   "Checked out " _ fileNm _ ", version: " _ rev)
		}
		set tempFile = ..DeployDirectory _ ..DeploymentPackageDirec _ fileNm
		set stat = ##class(%File).CopyFile(fullPath, tempFile, 1)
		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(userNm, "GetDeploymentPackageFromSvn Copy, status: " _ stat _ ", File: " _ tempFile _" from " _fullPath) 
	}
	else {
		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(userNm,   "Could not find file in SVN: " _ fullPath)
		set tSC = $$$ERROR($$$GeneralError, "Could not find file in SVN: " _ fileNm)
	}

 	Quit tSC

set sc = $$$OK
set retStr = ""
try {
	set $NAMESPACE = nmSp
	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("IHC.ITF.SrcCtrlPkg.CreateDeploymentPackageFiles.createDeploymentPackage: " _ compName)

	set direc = ..DeployDirectory _ ..DeploymentPackageDirec 
	IF ' ##class(%File).DirectoryExists(direc)
	 {
		 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Creating: " _ direc)
		 Do ##class(%File).CreateDirectoryChain(direc)
	     set tStat = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).CheckSvnSetup(userNm, passwd)
	 }
	set fName = nmSp _ "-" _ compName _".txt" 
	set tempFile = direc _  fName
	set srcCtrlFile = $$$USRRELEASEBASEDIR _ userNm _ $$$SVNSRCTRUNK _ ..DeploymentPackageDirec _ fName
	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("createDeploymentPackage - File: " _ tempFile _", Src ctrl: " _ srcCtrlFile)

	if (src = "SVN") 
	{
		Set sc = ..GetDeploymentPackageFromSvn(srcCtrlFile, userNm , passwd, "" )
		if ($$$ISOK(sc))
		{
			Do ##class(%File).CopyFile(srcCtrlFile, tempFile)
			set retStr = "; Copied from the Source Control: " _ tempFile
		}
		return sc
	}
	else
	{
		set sc = ..getCurrentDeploymentPackage(nmSp, compName, .retStr, tempFile ) 
	}

} catch(err)
{
	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "Exception: Could not create DeploymentPackage files " _ err)
	set sc = $$$ERROR("Could not create DeploymentPackage files " _ err.Data)
}			
return sc

set sc = $$$OK
Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("getCurrentDeploymentPackage: " _ tempFile)
Set file=##class(%File).%New(tempFile)

set sc = file.Open("WN")
if ($$$ISOK(sc))
{
	Do file.WriteLine("# DeploymentPackage file for: "  _ compName _ ", Namepsace: " _ nmSp )
	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Opened the file: " _ tempFile)

	Set tProductionName = ##class(Ens.Director).GetActiveProductionName()
   	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "tProductionName: " _ 	tProductionName)
   	Set tProduction = ##class(Ens.Config.Production).%OpenId(tProductionName,,.tStatus)
   	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("%OpenId " _ tStatus)

	#dim tItem As Ens.Config.Item
	Set tItem = ##class(Ens.Config.Production).OpenItemByConfigName(compName)
	If ' $IsObject(tItem)
	{
		Do file.Close()
		set retStr = "; " _ compName _ " is an invalid Object"
		QUIT $$$ERROR("Can't open object: " _ compName)	
	}
	else
	{

			// Analyze static DeploymentPackage for this component/config item

			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( tItem.Name _ ", ID: " _ tItem.%Id())
			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( tItem.Production.Name)
			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "tConfigItem properties: " _ tItem.ClassName _ ", " _ tItem.Comment)
			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "tConfigItem DeploymentPackage: " _ tItem.DeploymentPackage)

			/******** Process static DeploymentPackage ****/
			// 
			Do file.WriteLine(  "# Static DeploymentPackage")
			Set tStatus = tItem.GetStaticDeploymentPackage(.tStaticDeploymentPackage)
			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "GetStaticDeploymentPackage: " _ tStatus _", " _ $DATA(tStaticDeploymentPackage))
			If ($DATA(tStaticDeploymentPackage) = 10) {

				set ind = 1
				Set tDeploymentPackageName = ""
				Set tDeploymentPackageIndex = ""
				For {
					Set tDeploymentPackageIndex = $ORDER(tStaticDeploymentPackage(tDeploymentPackageIndex))
					Quit:(tDeploymentPackageIndex = "")

					Set tDeploymentPackageList = tStaticDeploymentPackage(tDeploymentPackageIndex)
					Set tDeploymentPackageName = $LG(tDeploymentPackageList,2)

					// Grab the value
					Set tCurrentValue = $LG(tDeploymentPackageList,3)


					Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "  StaticDeploymentPackage #$# " _
												tDeploymentPackageName _ ", val: " _ tCurrentValue )

					Do file.WriteLine(  "Static #$# " _ tDeploymentPackageName _"#$# "_tCurrentValue)
				} // end For

			} // End if $DATA(tStaticDeploymentPackage) = 10 
			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "  StaticDeploymentPackage END")

			Set tStatus = ##class(Ens.Director).GetHostDeploymentPackage(compName,.tHostDeploymentPackage)
			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile(  "  GetHostDeploymentPackage: " _ tStatus _ ", " _ $DATA(tHostDeploymentPackage))

			Do file.WriteLine(  "# Host DeploymentPackage")
			If ($DATA(tHostDeploymentPackage) = 10) {	

				Set tDeploymentPackageName = ""

				For {
					Set tDeploymentPackageName = $ORDER(tHostDeploymentPackage(tDeploymentPackageName))
					Quit:(tDeploymentPackageName = "")

					Set tCurrentValue = tHostDeploymentPackage(tDeploymentPackageName)


					Do file.WriteLine(  "Host #$# " _ tDeploymentPackageName _"#$# "_tCurrentValue)

				}  
			} // End if $DATA(tHostDeploymentPackage) = 10

			/***** Process adapter DeploymentPackage *****/
			Set tStatus = ##class(Ens.Director).GetAdapterDeploymentPackage(compName,.tAdapterDeploymentPackage)
			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "GetAdapterDeploymentPackage: " _ tStatus _ ", " _ $DATA(tAdapterDeploymentPackage))
			Do file.WriteLine(  "# Adapter DeploymentPackage")
			If ($DATA(tAdapterDeploymentPackage) = 10) {	

				Set tDeploymentPackageName = ""

				For {
					Set tDeploymentPackageName = $ORDER(tAdapterDeploymentPackage(tDeploymentPackageName))
					Quit:(tDeploymentPackageName = "")

					Set tCurrentValue = tAdapterDeploymentPackage(tDeploymentPackageName)


					Do file.WriteLine(  "Adapter #$# " _ tDeploymentPackageName _"#$# "_tCurrentValue)

				}  
			} // End if $DATA(tAdapterDeploymentPackage) = 10
	}
	set retStr = "; New file created from current component: " _ tempFile
	Do file.Close()
}
return sc


	set sc = $$$OK
	try {
		set $NAMESPACE = nmSp
		set sc = $$$OK
		set retStr = ""


		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("IHC.ITF.SrcCtrlPkg.CreateDeploymentPackageFiles.updateDeploymentPackage: " _ compName)


		set direc = ..DeployDirectory _ ..DeploymentPackageDirec 
		IF ' ##class(%File).DirectoryExists(direc)
		 {
			 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Creating: " _ direc)
			 Do ##class(%File).CreateDirectoryChain(direc)
			 set tStat = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).CheckSvnSetup(userNm, passwd)
		 }
		set fName = nmSp _ "-" _ compName _".txt" 
		set tempFile = direc _ fName
		set srcCtrlFile = $$$USRRELEASEBASEDIR _ userNm _ $$$SVNSRCTRUNK _ ..DeploymentPackageDirec _ fName
		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Files: " _ tempFile _", Src ctrl: " _ srcCtrlFile)

		if ( $$$ISERR(..GetDeploymentPackageFromSvn(srcCtrlFile, userNm , passwd, DeploymentPackageRev )))
		{		
			set retStr = "; Error in getting the file from SVN - " _ srcCtrlFile _ ", rev # " _ DeploymentPackageRev
			return sc
		}
		Do ##class(%File).CopyFile(srcCtrlFile, tempFile)

		Set tProductionName = ##class(Ens.Director).GetActiveProductionName()
   		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "tProductionName: " _ 	tProductionName)

		#dim tItem As Ens.Config.Item
		Set tItem = ##class(Ens.Config.Production).OpenItemByConfigName(compName)
		If ' $IsObject(tItem)
		{
			set sc = $$$ERROR("Can't open object: " _ compName)	
		}
		else
		{

		 	Set fileObj=##class(%Library.File).%New(tempFile)
		 	if ($IsObject(fileObj)) {

				set fileOpen = fileObj.Open("R") ; Read mode and as stream
				if ($$$ISERR(fileOpen))
				{
					set sc = $$$ERROR("Can not open file: " _ tempFile)
				}
				else
				{
										set fileInfo = ""
					set lnNum = 0
					set statNum = 0
				    While 'fileObj.AtEnd 
				    {
				         set readStr = fileObj.ReadLine(, .sc, .stat)
				         if ( ($L(readStr) > 0) && ($F(readStr, "#") '= 2) && ($F(readStr, "#$#") > 2) )
				         {
					         if ($ZSTRIP($PIECE(readStr, "#$#", 1),"<>W") = "Static")
					         {
						         set statNum = statNum + 1
					         }
					         else
					         {
					         	set lnNum = lnNum + 1
					         }
				         }
				    }
				    set pUpdArray = lnNum
				    Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile(" # of DeploymentPackage: Host " _ lnNum _ ", Static: " _ statNum)
				    Do fileObj.Rewind()
				    set lnNum = 1
				    While 'fileObj.AtEnd 
				    {
				         set readStr = fileObj.ReadLine(, .sc, .stat)
				         if ( ($L(readStr) > 0) && ($F(readStr, "#") '= 2) && ($F(readStr, "#$#") > 2))
				         {
					         set typeStr = $ZSTRIP($PIECE(readStr, "#$#", 1),"<>W") 
					         set keyStr = $ZSTRIP($PIECE(readStr, "#$#", 2),"<>W")
					         set valueStr = $ZSTRIP($PIECE(readStr, "#$#", 3),"<>W")


					         if ("Static" = typeStr)
					         {
						         if ("Comment" = keyStr)
						         {
						          set tItem.Comment = valueStr
						         }
						         elseif ("Category" = keyStr)
						         {
						          set tItem.Category = valueStr
						         }
						         elseif ("Enabled" = keyStr)
						         {
							         set tItem.Enabled = valueStr
						         }
						         elseif ("Schedule" = keyStr)
						         {
							         set tItem.Schedule = valueStr
						         }
						         elseif ("LogTraceEvents" = keyStr)
						         {
							         set tItem.LogTraceEvents = valueStr
						         }
						         elseif ("PoolSize" = keyStr)
						         {
							         set tItem.PoolSize = valueStr
						         }
						         else
						         {
						             Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "Did not Update: " _ typeStr _", " _ keyStr _", " _ valueStr)
						         }
					         }
					         else
					         {
					         	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "Add a row to array: " _ typeStr _", " _ keyStr _", " _ valueStr)
						        set pUpdArray(lnNum) = $LB(typeStr, keyStr, valueStr)
					         	set lnNum = lnNum + 1
					         }
				         }
				    }																	


					Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("UpdateDeploymentPackage- Array size: " _ pUpdArray)


					set updSc =  tItem.UpdateDeploymentPackage(.pUpdArray)
					Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Set new values: " _ updSc)
					set savSc =  tItem.%Save()
					Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("config save: " _ savSc)
					if ( ($$$ISERR(savSc)) || ($$$ISERR(updSc)))
					{
						set sc = $$$ERROR("Could not update (UpdateDeploymentPackage/%Save) DeploymentPackage for : " _ compName _ ", file: " _ tempFile)
					}
					Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "Updated DeploymentPackage for : " _ compName _ ", file: " _ tempFile)
				}
		 	}
		 	else
		 	{
			 	set sc = $$$ERROR("Can not create object for file: " _ tempFile)
		 	}
		}
	} catch(err)
	{
		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "Exception: Could not Update DeploymentPackage files " _ err)
		set sc = $$$ERROR("Could not update DeploymentPackage " _ err.Data)
	}		
	RETURN sc

 try
 {

	Set tSC = $$$OK 
	if ('##class(%File).Exists(fName))
	{
		set tempFile = ..DeployDirectory _ ..DeploymentPackageDirec _ fName

		if ('##class(%File).Exists(tempFile))
		{
			set tSC = $$$ERROR("Can't open file: " _ tempFile)
			RETURN tSC
		}
	}
	else
	{
		set tempFile = fName
	}
	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("checkInFile: " _ tempFile)

    set fullPath = $$$USRRELEASEBASEDIR _ userNm _ $$$SVNSRCTRUNK _ ..DeploymentPackageDirec 
    IF ' ##class(%File).DirectoryExists(fullPath)
	 {
		 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("Creating: " _ fullPath)
	     set tStat = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).CheckSvnSetup(userNm, passwd)
	 }


	set fullPath = fullPath _ fName
	Do ##class(%File).CopyFile(tempFile, fullPath)

	if (##class(%File).Exists(fullPath))
	{
		Set cmd = $$$SVNINFO _ " --username " _ %session.Data("svnUsrNm") _ " --password '" _ %session.Data("svnPsWd") _ "' " _ fullPath
		Set stat = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( cmd)
		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile(fullPath _ " svn info:" _ stat)

		If stat '= 0 	
		{
			// files not in svn, add the file
			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( $$$SVNINFO _" returned no information" )
			Set cmd = $$$SVNADD _ " --username " _ %session.Data("svnUsrNm") _ " --password '" _ %session.Data("svnPsWd") _ "' " _  fullPath  
			Set stat = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( cmd)
			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("svn add:" _ stat)
			If stat '= 0
			{
				Set tSC = $$$ERROR($$$EnsErrGeneral, "SVN add error for " _ fullPath)
				Return tSC
			}
		}
		set tempFile = ##class(%Library.File).TempFilename()
		set commentFile = ##class(%Library.File).TempFilename()
		Do ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).WriteToFile(commentFile, cmt _ ", Commited by " _ userNm)

		Set cmd = $$$SVNCOMMIT _ " --no-auth-cache --non-interactive --username " _ %session.Data("svnUsrNm") _ " --password '" _ %session.Data("svnPsWd")  _ "' -F "" " _ commentFile _ " "" " _ fullPath _ " > " _ tempFile
		Set stat = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( cmd)

	    Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("CheckinFiles: commit stat: " _ stat _ " file: " _ tempFile)

		if stat '= 0
		{
			  Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("SVN commit error: " _ $$$SVNCOMMIT _ " " _ fullPath)
			  Set tSC = $$$ERROR($$$EnsErrGeneral, "SVN commit error")
			  Do ##class(%Library.File).Delete(tempFile)
		}
		else
		{
			Set tSC = $$$OK
			set tComment = ##class(%Stream.TmpCharacter).%New()
			Do ##class(IHC.ITF.ITFCOMMON.Utility).findStringInFile(tempFile, "Committed", tComment)

			Do tComment.Rewind()
	    	set len = 32656
	    	#dim sc as %Status
	    	set commitComment = tComment.Read(.len, .sc)
	    	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile("SVN commit: " _ commitComment)
	    	set retStr = fullPath _ " - " _ commitComment
	    	Do ##class(%Library.File).Delete(tempFile)
	    	if ($L(retStr) = 0)
	    	{
		    	set retStr = "SVN commit complete, file may not be modified"
	    	}
		}
	}
	else
	{
		set tSC = $$$ERROR("Can't open file: " _ fullPath)
	}

 } catch err
 {
	 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFile( "Error: " _ err.Name _ " " _ err.Data _ " " _ ..DeployDirectory)
 }
 return tSC


	set fileNm = $$$USRRELEASEBASEDIR _ userNm _ $$$SVNSRCTRUNK _ ..DeploymentPackageDirec _ nmSp _ "-" _ compName _".txt"

    Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(userNm, "GetVersions: " _ fileNm _", Name: " _ compName _ "$")

	Do ##class(%File).Delete(fileNm)
	Set cmd= $$$SVNUPDATE _ " --username " _ %session.Data("svnUsrNm") _ " --password '" _ %session.Data("svnPsWd") _ "' " _  fileNm 

	Set status = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( cmd)

	if (status '= 0)
	{
		set fileInfo = $$$SVNUPDATE _ " failed for: " _ fileNm
	}
	if ##class(%File).Exists(fileNm)
	{
			set tempFile = 	fileNm _ "Temp"
			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(userNm,   "Checked out " _ fileNm)
			Set cmd= $$$SVNINFO _ fileNm _ " >> " _ tempFile

			Set status = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( cmd)
			if (status =0)
			{
	        	Set cmd=  $$$SVNLOG _" --username " _ %session.Data("svnUsrNm") _ " --password '" _ %session.Data("svnPsWd") _ "' " _ fileNm _ " >> " _ tempFile 

				Set status = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd( cmd)

	  			if ((status =0) && (##class(%File).Exists(tempFile)) )
	  			{
         			// Call the function to get svn information
         			Set fileInfo = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).GetFileContent(tempFile)       
	  			}
	  			else
	  			{
		  			SET fileInfo = "svn command :" _ $$$SVNLOG _ " failed: " _ $$$SVNLOG
	  			}
			}
			else
	  			{
		  			SET fileInfo = "svn command :" _ $$$SVNINFO _ " failed: " _ $$$SVNLOG
	  			}
	}
	else {
  			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(userNm,   "Could not find file in SVN: " _ fileNm)


	  		set fileInfo = "Could not find file in SVN: " _ fileNm

 	}

	Quit fileInfo

	set tSC = $$$OK
	try {

		 	NEW $NAMESPACE
     		set $NAMESPACE = "ITFCOMMON"
	 		set depCl = ##class(SrcCtrlDeploymentInfoWebService.SrcCtrlDeploymentInfoWebServiceSoap).%New()
	 		set depCl.Username = %session.Data("srcHistUsrNm")
		 	set depCl.Password = %session.Data("srcHistPsWd")
		 	Set depCl.Location = ..WSLocation
	 		set tSC = depCl.UpdateComponentImpl(compNm, nmSp, fileName, rev, fileInfo, dt, userNm)
	 		return tSC
	} catch err
	{
		 		If $ZERROR["<ZSOAP>" {
                	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(userNm,  %objlasterror)
                	Set tSC=$$$ERROR($$$GeneralError, "Error in updating Component in DB: " _ depCl.SoapFault.Reason.Text)
		 		} Else {
            		Set tSC=$$$ERROR($$$CacheError,$ZERROR)
		 		}
	}
	return tSC
